from collections import OrderedDict

def lru(capacity, operations):
    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(-1)
            # puts ignored
        return results
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.pop(key)
            cache[key] = value
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results
```

