def memo_cycle(definitions, name):
    visited = set()
    def helper(n):
        if n in visited:
            raise ValueError
        if n not in definitions:
            raise ValueError
        val = definitions[n]
        if isinstance(val, int):
            return val
        elif isinstance(val, list):
            visited.add(n)
            total = 0
            for dep in val:
